"""Migrated invoiced-order validation, workflow, and total recomputation rules."""

from decimal import Decimal, ROUND_HALF_UP
from typing import Any


class BusinessRuleViolation(Exception):
    code: str
    message: str

    def __init__(self, code: str, message: str) -> None:
        self.code = code
        self.message = message
        super().__init__(message)


_CENTS = Decimal("0.01")


def _numeric(value: Any) -> Decimal:
    """Apply Meridian NVL numeric semantics for missing and empty values."""
    if value is None or value == "":
        return Decimal("0")
    return Decimal(str(value))


def _cents(value: Decimal) -> Decimal:
    return value.quantize(_CENTS, rounding=ROUND_HALF_UP)


def _is_deleted(row: dict) -> bool:
    return row.get("DEL_FLG") == "Y"


def transition_invoiced(
    order: dict, new_status: str
) -> tuple[dict, list[str], list[str]]:
    """Apply ORD-003 and the workflow's invoiced-order transition behavior."""
    if order.get("STAT_CD") != "I":
        raise ValueError("transition_invoiced requires an invoiced order")

    updated_order = dict(order)

    if new_status == "I":
        return updated_order, [], []

    if new_status == "X":
        updated_order["STAT_CD"] = "X"
        return updated_order, ["ORD_CANC_INV"], ["credit_note"]

    raise BusinessRuleViolation(
        code="E5003",
        message="Invoiced order can only be cancelled",
    )


def recompute_total(
    order: dict, lines: list[dict]
) -> tuple[dict, list[dict], list[str]]:
    """Recompute live line extensions and a non-frozen order total."""
    updated_order = dict(order)
    updated_lines = [dict(line) for line in lines]

    # Cancelled orders were excluded by the legacy job. Invoiced totals are
    # deliberately frozen by the modernized requirement. Deleted headers are
    # likewise excluded from legacy reads and processing.
    if (
        _is_deleted(order)
        or order.get("STAT_CD") == "I"
        or order.get("STAT_CD") == "X"
    ):
        return updated_order, updated_lines, []

    total = Decimal("0")

    # Input list order is retained exactly, corresponding to the legacy
    # per-order line iteration order supplied to this single-order operation.
    for source_line, updated_line in zip(lines, updated_lines):
        if _is_deleted(source_line):
            continue

        extension = _cents(
            _numeric(source_line.get("QTY"))
            * _numeric(source_line.get("UNIT_PRC"))
        )
        updated_line["EXT_AMT"] = float(extension)
        total += extension

    discounted_total = _cents(
        total
        * (Decimal("100") - _numeric(order.get("DISC_PCT")))
        / Decimal("100")
    )

    updated_order["TOT_AMT"] = float(discounted_total)

    if _numeric(order.get("TOT_AMT")) != discounted_total:
        return updated_order, updated_lines, ["ORD_RETOTAL"]

    return updated_order, updated_lines, []
